/**
 * PredictionCard.js - Main Prediction Display Component
 * Week 2 - Days 10-14
 */

import React from 'react';
import { motion } from 'framer-motion';

const PredictionCard = ({ prediction }) => {
  const {
    ticker,
    timestamp,
    current_price,
    predicted_price,
    direction,
    change_percent,
    confidence,
  } = prediction;

  const isUp = direction.includes('UP');
  
  const formatDate = (isoString) => {
    const date = new Date(isoString);
    return date.toLocaleString('en-US', {
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
    });
  };

  return (
    <motion.div
      className="prediction-card"
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.5 }}
    >
      <div className="prediction-content">
        {/* Header */}
        <div className="prediction-header">
          <h2 className="prediction-ticker">{ticker}</h2>
          <span className="prediction-timestamp">{formatDate(timestamp)}</span>
        </div>

        {/* Prices */}
        <div className="prediction-prices">
          <motion.div
            className="price-box"
            initial={{ opacity: 0, x: -20 }}
            animate={{ opacity: 1, x: 0 }}
            transition={{ duration: 0.5, delay: 0.1 }}
          >
            <div className="price-label">Current Price</div>
            <div className="price-value">${current_price.toFixed(2)}</div>
          </motion.div>

          <motion.div
            className="price-box"
            initial={{ opacity: 0, x: -20 }}
            animate={{ opacity: 1, x: 0 }}
            transition={{ duration: 0.5, delay: 0.2 }}
          >
            <div className="price-label">Predicted Price</div>
            <div className="price-value">${predicted_price.toFixed(2)}</div>
          </motion.div>

          <motion.div
            className="price-box"
            initial={{ opacity: 0, x: -20 }}
            animate={{ opacity: 1, x: 0 }}
            transition={{ duration: 0.5, delay: 0.3 }}
          >
            <div className="price-label">Change</div>
            <div className="price-value" style={{ color: isUp ? '#6ee7b7' : '#fca5a5' }}>
              {change_percent >= 0 ? '+' : ''}{change_percent.toFixed(2)}%
            </div>
          </motion.div>
        </div>

        {/* Direction & Confidence */}
        <motion.div
          className="prediction-direction"
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.5, delay: 0.4 }}
        >
          <div className="direction-badge">
            <span>{isUp ? '⬆️' : '⬇️'}</span>
            <span>{direction}</span>
          </div>

          <div className="confidence-bar">
            <div className="confidence-label">Model Confidence</div>
            <div className="confidence-progress">
              <motion.div
                className="confidence-fill"
                initial={{ width: 0 }}
                animate={{ width: `${confidence * 100}%` }}
                transition={{ duration: 1, delay: 0.5 }}
              />
            </div>
            <div style={{ fontSize: '0.875rem', marginTop: '0.25rem' }}>
              {(confidence * 100).toFixed(1)}%
            </div>
          </div>
        </motion.div>
      </div>
    </motion.div>
  );
};

export default PredictionCard;
